// Output declarations become zero-initialised locals of the entry; `Base.X = src;` keeps its spelling on the material.
/// @name M_LpOutputs
export void M_LpOutputs(inout material Base)
{
    float3 Color = float3(0, 0, 0);
    float Alpha = 0;
    float2 Pair = float2(0, 0);
    Color = float3(1.0, 0.5, 0.25);
    Alpha = 0.5;
    Pair = float2(0.0, 1.0);
    Base.EmissiveColor = Color;
    Base.Opacity = Alpha;
}
